export type PlaybackMode = 'synth' | 'sample' | 'layer';

export type StepResolution = '16th' | '8th';

export interface SequencePreset {
  name: string;
  artist: string;
  bpm: number;
  scale: string;
  rootNote: string;
  stepCount?: number;
  swingPercentage?: number;
  timeSignature?: string;
  stepResolution?: StepResolution;
  tracks: {
    trackName: string;
    synthType: 'sine' | 'square' | 'sawtooth' | 'triangle' | 'distortion';
    /** Stereo position, -1 (left) to 1 (right). */
    pan?: number;
    distortion?: number;
    drive?: number;
    filterCutoff?: number;
    filterResonance?: number;
    detune?: number;
    envelope?: { attack: number; decay: number; sustain: number; release: number };
    rowNotes: string[];
    grid: number[][];
    ties?: boolean[][];
    delaySend?: number;
    reverbSend?: number;
    arpEnabled?: boolean;
    arpPattern?: 'up' | 'down' | 'updown' | 'random';
    portamento?: number;
    instrumentPreset?: string;
    playbackMode?: PlaybackMode;
    sampleSet?: string;
    sampleBlend?: number;
  }[];
}

export interface FilterEnvelope {
  initialCutoff: number;
  finalCutoff: number;
  rampDuration: number;
  Q: number;
}

export interface VibratoConfig {
  /** Pitch depth in cents (±). */
  depth: number;
  rate: number;
  /** Seconds before vibrato fades in (players add it after the attack). */
  delay?: number;
}

export interface DistortionConfig {
  amount: number;
  oversample?: 'none' | '2x' | '4x';
}

export interface HighPassConfig {
  frequency: number;
}

export interface InstrumentPreset {
  name: string;
  label: string;
  /** 'subtractive' (oscillators → filter → amp, default) or 'pluck' (Karplus–Strong string). */
  engine?: 'subtractive' | 'pluck';
  pluck?: { brightness: number; decay: number };
  oscType: OscillatorType;
  /** Second oscillator: waveform (defaults to oscType), octave offset, level 0–1 and detune in cents. */
  osc2Type?: OscillatorType;
  osc2Octave?: number;
  osc2Level?: number;
  detune?: number;
  /** Breath / bow / air noise mixed into the filter, 0–1. */
  noise?: number;
  /** 0 = fixed filter cutoff, 1 = cutoff follows pitch fully (default 0.5). */
  keyTracking?: number;
  ampAttack: number;
  ampDecay: number;
  ampSustain: number;
  ampRelease: number;
  velocitySensitivity: number;
  filterEnvelope?: FilterEnvelope;
  vibrato?: VibratoConfig;
  distortion?: DistortionConfig;
  highPassFilter?: HighPassConfig;
  sampleSet?: string;
}

// Each instrument has two voices:
//  • realistic: `sampleSet` (recorded samples, used in 'sample' / 'layer' playback mode)
//  • retro:     the synth patch below (used in 'synth' mode, RETRO mode, and as fallback for missing samples)
// Plucked strings use the Karplus–Strong engine; everything else is subtractive
// (2 oscillators + optional breath noise → key-tracked filter envelope → exponential ADSR).
// Vibrato depth is in cents.
